def count_triples(n, a, b):
    """
    Helper function to count valid triples (a[i], a[j], a[k]) of a where i < j < k, 
    and a[i] + a[j] + a[k] is a multiple of 3.
    """
    if a <= b:
        count = 0
        for i in range(a, b):
            j = i + 1
            k = b
            while j < k:
                if (i * i + j * j + k * k) % 3 == 0:
                    count += 1
                j += 1
        return count
    else:
        count = 0
        for i in range(n - 2, -1, -1):
            j = i + 1
            k = n
            while j < k:
                if (i * i + j * j + k * k) % 3 == 0:
                    count += 1
                j += 1
        return count


